def ncomp(a):
 s={(i,j) for i,row in enumerate(a) for j,x in enumerate(row) if x}; n=0
 while s:
  n+=1; stack=[s.pop()]
  while stack:
   i,j=stack.pop()
   for p in [(i+1,j),(i-1,j),(i,j+1),(i,j-1)]:
    if p in s:s.remove(p);stack.append(p)
 return n
