def d4maps(a):
 maps=[];cur=a
 for rot in range(4):
  maps.append(('r'+str(rot),norm(cur)))
  maps.append(('f'+str(rot),norm([row[::-1] for row in cur])))
  cur=[list(row) for row in zip(*cur[::-1])]
 return maps
def rels(a,b):return [name for name,x in d4maps(a) if x==norm(b)]
